const rawRole=u=>String(u?.role||'').toUpperCase();
const roleOf=u=>rawRole(u)==='SUPER_ADMIN'?'ADMIN':rawRole(u);
const isSuperAdmin=u=>rawRole(u)==='SUPER_ADMIN'||u?.is_super_admin===true;
const isAdmin=u=>roleOf(u)==='ADMIN';
const isManager=u=>roleOf(u)==='MANAGER';
const sign=u=>jwt.sign({id:u.id,name:u.name,email:u.email,role:roleOf(u),is_super_admin:isSuperAdmin(u)},process.env.JWT_SECRET||'dev-secret',{expiresIn:'8h'});
async function auth(req,res,next){try{const h=req.headers.authorization||'';req.user=jwt.verify(h.replace('Bearer ',''),process.env.JWT_SECRET||'dev-secret');next()}catch(e){res.status(401).json({error:'Unauthorized'})}}
const requireAdmin=(req,res,next)=>isAdmin(req.user)?next():res.status(403).json({error:'Admin access required'});
const requireSuperAdminForAdminCreation=(req,res,next)=>isSuperAdmin(req.user)?next():res.status(403).json({error:'Only Super Admin can create or assign Admin users'});
const requireSuperAdmin=(req,res,next)=>isSuperAdmin(req.user)?next():res.status(403).json({error:'Super Admin access required'});
const requireManagerOrAdmin=(req,res,next)=>(isAdmin(req.user)||isManager(req.user))?next():res.status(403).json({error:'Admin or manager access required'});
const audit=async(req,action,entity,entityId)=>{try{await pool.query('INSERT INTO audit_logs(user_id,action,entity,entity_id,ip) VALUES($1,$2,$3,$4,$5)',[req.user?.id,action,entity,entityId,req.ip])}catch(e){console.error('[AUDIT]',e.message)}};
const hashToken=t=>crypto.createHash('sha256').update(t).digest('hex');
const makeToken=()=>crypto.randomBytes(32).toString('hex');

const CIBIL_PARSER_VERSION='parser-v14-cibil-sanctioned-balance-emi';


async function activeUsers(){return (await pool.query("SELECT id,name,email,role,manager_id,active,monthly_cost FROM users WHERE active=true AND deleted_at IS NULL AND UPPER(role)<>'SUPER_ADMIN' ORDER BY name")).rows}
async function directReports(userId){return (await pool.query("SELECT id,name,email,role,manager_id FROM users WHERE active=true AND deleted_at IS NULL AND UPPER(role)<>'SUPER_ADMIN' AND manager_id=$1 ORDER BY name",[userId])).rows}
async function canSeeUser(actor,targetId){if(isAdmin(actor))return true;if(actor.id===targetId)return true;if(isManager(actor)){const r=await pool.query('SELECT 1 FROM users WHERE id=$1 AND manager_id=$2 AND active=true AND deleted_at IS NULL',[targetId,actor.id]);return !!r.rowCount}return false}
async function visibleUserIds(actor){if(isAdmin(actor))return (await pool.query("SELECT id FROM users WHERE active=true AND deleted_at IS NULL AND UPPER(role)<>'SUPER_ADMIN'")).rows.map(x=>x.id);if(isManager(actor)){return [actor.id,...(await directReports(actor.id)).map(x=>x.id)]}return [actor.id]}
async function canAccessCustomer(actor,customerId){const ids=await visibleUserIds(actor);if(isAdmin(actor))return !!(await pool.query('SELECT 1 FROM customers WHERE id=$1 AND deleted_at IS NULL',[customerId])).rowCount;return !!(await pool.query('SELECT 1 FROM customers c WHERE c.id=$1 AND c.deleted_at IS NULL AND EXISTS (SELECT 1 FROM leads l WHERE l.customer_id=c.id AND (l.assigned_to=ANY($2) OR l.assigned_to IS NULL))',[customerId,ids])).rowCount}
async function canAssignLeadTo(actor,targetId){if(isAdmin(actor))return true;if(actor.id===targetId)return true;if(isManager(actor)){const r=await pool.query('SELECT 1 FROM users WHERE id=$1 AND manager_id=$2 AND active=true AND deleted_at IS NULL',[targetId,actor.id]);return !!r.rowCount}return false}

