app.get('/api/auth/profile-photo',async(req,res)=>{const email=String(req.query?.email||'').trim();if(!email)return res.status(400).json({error:'Email is required'});const r=await pool.query('SELECT id,profile_photo_data,profile_photo_mime FROM users WHERE lower(email)=lower($1) AND active=true AND deleted_at IS NULL',[email]);if(!r.rows[0]?.profile_photo_data)return res.status(404).end();res.set('Content-Type',r.rows[0].profile_photo_mime||'image/jpeg');res.set('Cache-Control','no-store');res.end(r.rows[0].profile_photo_data)});
app.post('/api/auth/login',async(req,res)=>{const {email,password}=req.body;const r=await pool.query('SELECT * FROM users WHERE lower(email)=lower($1) AND active=true AND deleted_at IS NULL',[email]);if(!r.rows[0]||!await bcrypt.compare(password,r.rows[0].password_hash))return res.status(401).json({error:'Invalid credentials'});res.json({token:sign(r.rows[0]),user:{id:r.rows[0].id,name:r.rows[0].name,email:r.rows[0].email,role:roleOf(r.rows[0]),is_super_admin:isSuperAdmin(r.rows[0]),profile_photo_url:`/api/users/${r.rows[0].id}/profile-photo`}})});
