app.get('/api/profile',auth,async(req,res)=>{const r=await pool.query('SELECT id,name,email,role,manager_id,monthly_cost,active FROM users WHERE id=$1 AND active=true AND deleted_at IS NULL',[req.user.id]);if(!r.rows[0])return res.status(404).json({error:'User not found'});res.json({...r.rows[0],role:roleOf(r.rows[0]),is_super_admin:isSuperAdmin(r.rows[0]),profile_photo_url:`/api/users/${req.user.id}/profile-photo`})});
app.patch('/api/profile',auth,(req,res)=>{upload.single('profile_photo')(req,res,async err=>{if(err)return res.status(400).json({error:err.message});const name=String(req.body?.name||'').trim();if(!name)return res.status(400).json({error:'Name is required'});const r=await pool.query('UPDATE users SET name=$1 WHERE id=$2 AND active=true AND deleted_at IS NULL RETURNING id,name,email,role,manager_id,monthly_cost,active',[name,req.user.id]);if(!r.rows[0])return res.status(404).json({error:'User not found'});await audit(req,'PROFILE_UPDATED','user',req.user.id);res.json({...r.rows[0],role:roleOf(r.rows[0]),is_super_admin:isSuperAdmin(r.rows[0]),profile_photo_url:`/api/users/${req.user.id}/profile-photo`})});});
app.patch('/api/profile/photo',auth,(req,res)=>{upload.single('profile_photo')(req,res,async err=>{if(err)return res.status(400).json({error:err.message});if(!req.file||!String(req.file.mimetype||'').startsWith('image/'))return res.status(400).json({error:'Please upload an image file.'});await pool.query('UPDATE users SET profile_photo_data=$1,profile_photo_mime=$2 WHERE id=$3',[req.file.buffer,req.file.mimetype,req.user.id]);await audit(req,'PROFILE_PHOTO_UPDATED','user',req.user.id);res.json({ok:true,profile_photo_url:`/api/users/${req.user.id}/profile-photo?ts=${Date.now()}`})})});
app.patch('/api/users/:id/admin-password',auth,requireAdmin,async(req,res)=>{const targetId=String(req.params.id||'');const newPassword=String(req.body?.new_password||'');if(newPassword.length<8)return res.status(400).json({error:'New password must be at least 8 characters.'});const target=await pool.query('SELECT id,name,email,role,manager_id,active FROM users WHERE id=$1 AND active=true AND deleted_at IS NULL',[targetId]);if(!target.rows[0])return res.status(404).json({error:'User not found'});if(isSuperAdmin(target.rows[0]))return res.status(403).json({error:'Super Admin password cannot be changed from user management.'});if(req.user.id===targetId)return res.status(400).json({error:'Use My Profile to change your own password.'});if(!await canSeeUser(req.user,targetId))return res.status(403).json({error:'You can only change passwords for users under your hierarchy.'});const hash=await bcrypt.hash(newPassword,12);await pool.query('UPDATE users SET password_hash=$1 WHERE id=$2',[hash,targetId]);await audit(req,'ADMIN_PASSWORD_RESET','user',targetId);res.json({ok:true,message:`Password updated for ${target.rows[0].name}.`})});
app.patch('/api/profile/password',auth,async(req,res)=>{const currentPassword=String(req.body?.current_password||'');const newPassword=String(req.body?.new_password||'');if(newPassword.length<8)return res.status(400).json({error:'New password must be at least 8 characters.'});const r=await pool.query('SELECT password_hash FROM users WHERE id=$1 AND active=true AND deleted_at IS NULL',[req.user.id]);if(!r.rows[0]||!await bcrypt.compare(currentPassword,r.rows[0].password_hash))return res.status(400).json({error:'Current password is incorrect.'});const hash=await bcrypt.hash(newPassword,12);await pool.query('UPDATE users SET password_hash=$1 WHERE id=$2',[hash,req.user.id]);await audit(req,'PASSWORD_CHANGED','user',req.user.id);res.json({ok:true,message:'Password updated successfully.'})});
app.post('/api/auth/forgot-password',async(req,res)=>{const email=String(req.body?.email||'').trim().toLowerCase();if(!email)return res.status(400).json({error:'Email is required.'});const r=await pool.query('SELECT id,name,email FROM users WHERE lower(email)=lower($1) AND active=true AND deleted_at IS NULL',[email]);if(!r.rows[0])return res.status(404).json({error:'No active user was found with this email address.'});const password=crypto.randomBytes(6).toString('base64url').slice(0,10)+'A1!';const hash=await bcrypt.hash(password,12);const smtpHost=process.env.SMTP_HOST,smtpPort=Number(process.env.SMTP_PORT||587),smtpUser=process.env.SMTP_USER,smtpPass=process.env.SMTP_PASS,from=process.env.SMTP_FROM||smtpUser;if(!smtpHost||!smtpUser||!smtpPass||!from)return res.status(503).json({error:'Password reset email service is not configured. Please contact the administrator.'});try{const transporter=nodemailer.createTransport({host:smtpHost,port:smtpPort,secure:String(process.env.SMTP_SECURE||'false').toLowerCase()==='true',auth:{user:smtpUser,pass:smtpPass}});await transporter.sendMail({from,to:r.rows[0].email,subject:'LoanCRM password reset',text:'Hello '+r.rows[0].name+',\\n\\nYour LoanCRM password has been reset.\\n\\nTemporary password: '+password+'\\n\\nPlease sign in and change your password from My Profile.\\n\\nRegards,\\nLoanCRM'});await pool.query('UPDATE users SET password_hash=$1 WHERE id=$2',[hash,r.rows[0].id]);res.json({ok:true,message:'A new temporary password has been sent to your registered email address.'})}catch(e){console.error('[FORGOT PASSWORD]',e);res.status(502).json({error:'Unable to send the password reset email. Please contact the administrator.'})}});
app.get('/api/dashboard',auth,async(req,res)=>{try{const ids=await visibleUserIds(req.user);const q=async(sql,p=[ids])=>Number((await pool.query(sql,p)).rows[0]?.n||0);const isExecutive=isAdmin(req.user);const sixMonths=(await pool.query("SELECT to_char(date_trunc('month',m),'Mon YYYY') label, to_char(date_trunc('month',m),'YYYY-MM') key FROM generate_series(date_trunc('month',now())-interval '5 months',date_trunc('month',now()),interval '1 month') m ORDER BY m")).rows;const monthly=await Promise.all(sixMonths.map(async m=>{const [leads,applications,disbursed,disbursedValue]=await Promise.all([q("SELECT count(*) n FROM leads l JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE l.created_at>=to_date($2,'YYYY-MM') AND l.created_at<to_date($2,'YYYY-MM')+interval '1 month' AND (l.assigned_to=ANY($1) OR l.assigned_to IS NULL)",[ids,m.key]),q("SELECT count(*) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL WHERE a.created_at>=to_date($2,'YYYY-MM') AND a.created_at<to_date($2,'YYYY-MM')+interval '1 month' AND (a.assigned_to=ANY($1) OR a.assigned_to IS NULL)",[ids,m.key]),q("SELECT count(*) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL WHERE a.status='DISBURSED' AND a.updated_at>=to_date($2,'YYYY-MM') AND a.updated_at<to_date($2,'YYYY-MM')+interval '1 month' AND (a.assigned_to=ANY($1) OR a.assigned_to IS NULL)",[ids,m.key]),Number((await pool.query("SELECT COALESCE(sum(a.disbursed_amount),0) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL WHERE a.status='DISBURSED' AND a.updated_at>=to_date($2,'YYYY-MM') AND a.updated_at<to_date($2,'YYYY-MM')+interval '1 month' AND (a.assigned_to=ANY($1) OR a.assigned_to IS NULL)",[ids,m.key])).rows[0]?.n||0)]);return {label:m.label,leads,applications,disbursed,disbursedValue}}));const customers=await q('SELECT count(DISTINCT c.id) n FROM customers c LEFT JOIN leads l ON l.customer_id=c.id WHERE c.deleted_at IS NULL AND (l.assigned_to=ANY($1) OR l.assigned_to IS NULL)');const leads=await q('SELECT count(*) n FROM leads l JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE l.assigned_to=ANY($1) OR l.assigned_to IS NULL');const applications=await q('SELECT count(*) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL WHERE a.assigned_to=ANY($1) OR a.assigned_to IS NULL');const disbursed=await q("SELECT count(*) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL WHERE a.status='DISBURSED' AND (a.assigned_to=ANY($1) OR a.assigned_to IS NULL)");const disbursedValue=Number((await pool.query("SELECT COALESCE(sum(a.disbursed_amount),0) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL WHERE a.status='DISBURSED' AND (a.assigned_to=ANY($1) OR a.assigned_to IS NULL)",[ids])).rows[0]?.n||0);const totalCommissionEarned=Number((await pool.query("SELECT COALESCE(sum(COALESCE(a.disbursed_amount,0)*COALESCE(l.commission_pct,0)/100),0) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL LEFT JOIN lenders l ON l.id=a.lender_id WHERE a.status='DISBURSED' AND (a.assigned_to=ANY($1) OR a.assigned_to IS NULL)",[ids])).rows[0]?.n||0);const followups=await q('SELECT count(*) n FROM followups f JOIN leads l ON l.id=f.lead_id JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE f.completed=false AND (f.assigned_to=ANY($1) OR f.assigned_to IS NULL)');const pendingAssignments=await q("SELECT count(*) n FROM leads l JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE l.assignment_status='PENDING' AND l.assigned_to=ANY($1)");const completedFollowups=await q("SELECT count(*) n FROM followups f JOIN leads l ON l.id=f.lead_id JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE f.completed=true AND f.created_at>=now()-interval '30 days' AND (f.assigned_to=ANY($1) OR f.assigned_to IS NULL)");const recentFollowups=completedFollowups+followups;const followupEfficiency=recentFollowups?Math.round(completedFollowups*100/recentFollowups):0;const overdue=await q("SELECT count(*) n FROM followups f JOIN leads l ON l.id=f.lead_id JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE f.completed=false AND f.due_at<now() AND (f.assigned_to=ANY($1) OR f.assigned_to IS NULL)");const attention={overdueFollowups:overdue,pendingAssignments,unprocessedApplications:await q("SELECT count(*) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL WHERE a.status IN ('NEW','PROCESSING') AND a.created_at<now()-interval '48 hours' AND (a.assigned_to=ANY($1) OR a.assigned_to IS NULL)"),uncontactedLeads:await q("SELECT count(*) n FROM leads l JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE l.status IN ('NEW','OPEN') AND l.created_at<now()-interval '24 hours' AND (l.assigned_to=ANY($1) OR l.assigned_to IS NULL)")};const funnelRows=(await pool.query("SELECT COALESCE(NULLIF(upper(stage),''),'NEW LEAD') stage,count(*)::int n FROM leads l JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE l.assigned_to=ANY($1) OR l.assigned_to IS NULL GROUP BY 1 ORDER BY n DESC",[ids])).rows;const conversionBase=await q("SELECT count(*) n FROM leads l JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE l.assigned_to=ANY($1) OR l.assigned_to IS NULL",[ids]);const conversionWon=await q("SELECT count(DISTINCT l.id) n FROM leads l JOIN applications a ON a.customer_id=l.customer_id AND a.status IN ('APPROVED','DISBURSED') JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE l.assigned_to=ANY($1) OR l.assigned_to IS NULL",[ids]);const team= isExecutive ? (await pool.query("SELECT id,name,role FROM users WHERE active=true AND deleted_at IS NULL AND UPPER(role)<>'SUPER_ADMIN' ORDER BY name")).rows : (await directReports(req.user.id));const teamPerformance=await Promise.all(team.map(async u=>{const uid=[u.id];const [tl,ta,td,tf]=await Promise.all([q("SELECT count(*) n FROM leads l JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE l.assigned_to=ANY($1)",[uid]),q("SELECT count(*) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL WHERE a.assigned_to=ANY($1)",[uid]),q("SELECT count(*) n FROM applications a JOIN customers c ON c.id=a.customer_id AND c.deleted_at IS NULL WHERE a.assigned_to=ANY($1) AND a.status='DISBURSED'",[uid]),q("SELECT count(*) n FROM followups f JOIN leads l ON l.id=f.lead_id JOIN customers c ON c.id=l.customer_id AND c.deleted_at IS NULL WHERE f.assigned_to=ANY($1) AND f.completed=true AND f.created_at>=now()-interval '30 days'",[uid])]);return {id:u.id,name:u.name,role:u.role,leads:tl,applications:ta,disbursed:td,completedFollowups:tf}}));res.json({customers,leads,applications,disbursed,disbursedValue,totalCommissionEarned,followups,pendingAssignments,monthly,attention,efficiency:{followupCompletion30d:followupEfficiency,leadToApprovedRate:conversionBase?Math.round(conversionWon*100/conversionBase):0},funnel:funnelRows,teamPerformance,executive:isExecutive})}catch(e){console.error('[DASHBOARD]',e);res.status(500).json({error:'Dashboard metrics could not be loaded.'})}});
