app.get('/api/applications',auth,async(req,res)=>{const view=req.query.view||'self';const ids=await visibleUserIds(req.user);let sql='SELECT a.*,c.name customer_name,COALESCE(l2.name,l.name) lender_name,p.name product_name,u.name assigned_name FROM applications a JOIN customers c ON c.id=a.customer_id LEFT JOIN lenders l2 ON l2.id=a.lender_id LEFT JOIN loan_products p ON p.id=a.product_id LEFT JOIN lenders l ON l.id=p.lender_id LEFT JOIN users u ON u.id=a.assigned_to WHERE 1=1';const params=[];if(view==='unassigned'){sql+=' AND a.assigned_to IS NULL'}else if(view==='all'){if(!isAdmin(req.user))return res.status(403).json({error:'Application Register is restricted to Admin users'})}else if(view==='team'){if(!isAdmin(req.user)&&!isManager(req.user))return res.status(403).json({error:'Team applications are not available for your role'});let allowed=ids;if(req.query.assignee&&req.query.assignee!=='all'){if(!ids.includes(req.query.assignee))return res.status(403).json({error:'You can only view applications assigned to members of your team'});allowed=[req.query.assignee]}sql+=' AND a.assigned_to=ANY($1)';params.push(allowed)}else{sql+=' AND a.assigned_to=$1';params.push(req.user.id)}sql+=' ORDER BY a.created_at DESC';res.json((await pool.query(sql,params)).rows)});
app.post('/api/applications',auth,async(req,res)=>{const b=req.body;if(!b.customer_id)return res.status(400).json({error:'Customer is required'});if(!await canAccessCustomer(req.user,b.customer_id))return res.status(403).json({error:'You cannot create an application for this customer'});const no='APP-'+Date.now();const status=b.status||'PROCESSING';const assignee=b.assigned_to||req.user.id;if(!await canAssignLeadTo(req.user,assignee))return res.status(403).json({error:'You cannot assign this application to that user'});const r=await pool.query('INSERT INTO applications(customer_id,product_id,lender_id,application_type,assigned_to,application_no,requested_amount,status,remarks) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *',[b.customer_id,b.product_id||null,b.lender_id||null,b.application_type||null,assignee,no,b.requested_amount||null,status,b.remarks||null]);await audit(req,'LOAN_APPLICATION_CREATED','application',r.rows[0].id);res.status(201).json(r.rows[0])});
