app.post('/api/customers',auth,async(req,res)=>{const {name,phone,email,pan,city,employment_type,monthly_income,mother_maiden_name,spouse_name}=req.body;if(!name||!String(name).trim())return res.status(400).json({error:'Customer name is required'});const r=await pool.query('INSERT INTO customers(name,phone,email,pan,city,employment_type,monthly_income,mother_maiden_name,spouse_name) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *',[name,phone,email,pan,city,employment_type,monthly_income||null,mother_maiden_name||null,spouse_name||null]);await audit(req,'CUSTOMER_CREATED','customer',r.rows[0].id);res.status(201).json(r.rows[0])});
app.patch('/api/customers/:id',auth,async(req,res)=>{if(!await canAccessCustomer(req.user,req.params.id))return res.status(403).json({error:'You cannot edit this customer'});const allowed=['name','phone','email','pan','city','employment_type','monthly_income','mother_maiden_name','spouse_name'];const existing=await pool.query('SELECT * FROM customers WHERE id=$1 AND deleted_at IS NULL',[req.params.id]);if(!existing.rows[0])return res.status(404).json({error:'Customer not found'});const before=existing.rows[0];const changes={};const values={};for(const f of allowed){if(Object.prototype.hasOwnProperty.call(req.body,f)){const v=f==='monthly_income'?(req.body[f]===''?null:req.body[f]):(req.body[f]===''?null:req.body[f]);if(String(before[f]??'')!==String(v??'')){changes[f]={from:before[f]??null,to:v??null};values[f]=v}}}if(!Object.keys(changes).length)return res.json(before);if(values.name!==undefined&&!String(values.name||'').trim())return res.status(400).json({error:'Customer name cannot be empty'});const client=await pool.connect();try{await client.query('BEGIN');const sets=[];const params=[];let i=1;for(const f of allowed){if(Object.prototype.hasOwnProperty.call(values,f)){sets.push(`${f}=$${i++}`);params.push(values[f])}}params.push(req.params.id);const updated=await client.query(`UPDATE customers SET ${sets.join(',')},updated_at=now() WHERE id=$${i} RETURNING *`,params);await client.query(`INSERT INTO customer_change_history(customer_id,changed_by,action,changes,before_data,after_data) VALUES($1,$2,'UPDATED',$3,$4,$5)`,[req.params.id,req.user.id,JSON.stringify(changes),JSON.stringify(before),JSON.stringify(updated.rows[0])]);await client.query('COMMIT');await audit(req,'CUSTOMER_UPDATED','customer',req.params.id);res.json(updated.rows[0])}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}});
app.delete('/api/customers/:id',auth,requireManagerOrAdmin,async(req,res)=>{const existing=await pool.query('SELECT * FROM customers WHERE id=$1 AND deleted_at IS NULL',[req.params.id]);if(!existing.rows[0])return res.status(404).json({error:'Active customer not found'});const r=await pool.query('UPDATE customers SET deleted_at=now(),deleted_by=$1,updated_at=now() WHERE id=$2 RETURNING id,name,deleted_at',[req.user.id,req.params.id]);await pool.query(`INSERT INTO customer_change_history(customer_id,changed_by,action,changes,before_data,after_data) VALUES($1,$2,'DELETED',$3,$4,$5)`,[req.params.id,req.user.id,JSON.stringify({deleted_at:{from:null,to:r.rows[0].deleted_at}}),JSON.stringify(existing.rows[0]),JSON.stringify(r.rows[0])]);await audit(req,'CUSTOMER_SOFT_DELETED','customer',req.params.id);res.json({ok:true,customer:r.rows[0]})});

app.get('/api/leads',auth,async(req,res)=>{const ids=await visibleUserIds(req.user);const mode=req.query.view||'all';let where='(l.assigned_to=ANY($1) OR l.assigned_to IS NULL)';let params=[ids];if(mode==='self'){where='l.assigned_to=$1';params=[req.user.id]}else if(mode==='team'){let teamIds=[];if(isAdmin(req.user)){teamIds=ids.filter(id=>id!==req.user.id)}else if(isManager(req.user)){teamIds=(await directReports(req.user.id)).map(x=>x.id)}const assignee=String(req.query.assignee||'all');if(assignee!=='all'){if(!teamIds.includes(assignee))return res.status(403).json({error:'You can only view leads assigned to members of your team'});where='l.assigned_to=$1';params=[assignee]}else{where='l.assigned_to=ANY($1)';params=[teamIds]}}else if(mode==='unassigned'){where='l.assigned_to IS NULL'}const r=await pool.query(`SELECT l.*,c.name customer_name,c.phone,u.name assigned_name,u.role assigned_role FROM leads l JOIN customers c ON c.id=l.customer_id LEFT JOIN users u ON u.id=l.assigned_to WHERE ${where} ORDER BY l.assignment_status='PENDING' DESC,l.created_at DESC`,params);res.json(r.rows)});
app.post('/api/leads',auth,async(req,res)=>{const {customer_id,source,status='NEW',notes,next_followup,assigned_to=null}=req.body;let target=assigned_to||null;if(target&&!await canAssignLeadTo(req.user,target))return res.status(403).json({error:'You cannot assign leads to this user'});if(target&&String((await pool.query('SELECT role FROM users WHERE id=$1',[target])).rows[0]?.role).toUpperCase()==='TEAM_MEMBER'){const pending=await pool.query("SELECT 1 FROM leads WHERE assigned_to=$1 AND assignment_status='PENDING'",[target]);if(pending.rowCount)return res.status(409).json({error:'This team member already has a pending lead assignment.'})}const assignmentStatus=target?'PENDING':'UNASSIGNED';const r=await pool.query('INSERT INTO leads(customer_id,source,status,assigned_to,notes,next_followup,assignment_status,stage) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',[customer_id,source,status,target,notes,next_followup||null,assignmentStatus,'NEW LEAD']);await audit(req,'LEAD_CREATED','lead',r.rows[0].id);res.status(201).json(r.rows[0])});
app.patch('/api/leads/:id/assign',auth,async(req,res)=>{const target=await pool.query('SELECT * FROM users WHERE id=$1 AND active=true AND deleted_at IS NULL',[req.body.assigned_to]);if(!target.rows[0])return res.status(400).json({error:'Target user not found'});if(!await canAssignLeadTo(req.user,req.body.assigned_to))return res.status(403).json({error:'You cannot assign this lead to that user'});const tRole=roleOf(target.rows[0]);if(tRole==='TEAM_MEMBER'){const pending=await pool.query("SELECT 1 FROM leads WHERE assigned_to=$1 AND assignment_status='PENDING' AND id<>$2",[req.body.assigned_to,req.params.id]);if(pending.rowCount)return res.status(409).json({error:'This team member already has one pending assignment.'})}const r=await pool.query("UPDATE leads SET assigned_to=$1,assignment_status='PENDING',updated_at=now() WHERE id=$2 RETURNING *",[req.body.assigned_to,req.params.id]);if(!r.rows[0])return res.status(404).json({error:'Lead not found'});await audit(req,'LEAD_ASSIGNED','lead',req.params.id);res.json(r.rows[0])});
app.patch('/api/leads/:id/stage',auth,async(req,res)=>{const lead=await pool.query('SELECT * FROM leads WHERE id=$1',[req.params.id]);if(!lead.rows[0])return res.status(404).json({error:'Lead not found'});if(!(await canSeeUser(req.user,lead.rows[0].assigned_to)) && lead.rows[0].assigned_to!==null)return res.status(403).json({error:'You cannot update this lead'});const stages=['NEW LEAD','CONTACTED','FOLLOW-UP','DOCUMENTS PENDING','DOCUMENTS RECEIVED','CIBIL ANALYSIS','ELIGIBILITY CHECK','LOGIN INITIATED','LOGIN SUBMITTED','SANCTIONED','DISBURSED','REJECTED','ON HOLD','CLOSED'];if(!stages.includes(req.body.stage))return res.status(400).json({error:'Invalid lead stage'});const followupDate=req.body.followup_date||null;if(req.body.stage==='FOLLOW-UP'){if(!followupDate)return res.status(400).json({error:'Follow-up date and time are mandatory when stage is FOLLOW-UP'});const dt=new Date(followupDate);if(Number.isNaN(dt.getTime()))return res.status(400).json({error:'Invalid follow-up date and time'});}const r=await pool.query("UPDATE leads SET stage=$1,status=$1,next_followup=CASE WHEN $1='FOLLOW-UP' THEN $2::timestamptz ELSE next_followup END,assignment_status=CASE WHEN $1 IN ('CLOSED','REJECTED') THEN 'COMPLETED' ELSE assignment_status END,updated_at=now() WHERE id=$3 RETURNING *",[req.body.stage,followupDate,req.params.id]);if(req.body.stage==='FOLLOW-UP'){const existingFollowup=await pool.query("SELECT id FROM followups WHERE lead_id=$1 AND completed=false ORDER BY created_at DESC LIMIT 1",[req.params.id]);if(existingFollowup.rows[0])await pool.query("UPDATE followups SET assigned_to=$1,due_at=$2,notes=COALESCE($3,notes) WHERE id=$4",[r.rows[0].assigned_to||req.user.id,followupDate,req.body.comment||null,existingFollowup.rows[0].id]);else await pool.query("INSERT INTO followups(lead_id,assigned_to,due_at,notes,completed) VALUES($1,$2,$3,$4,false)",[req.params.id,r.rows[0].assigned_to||req.user.id,followupDate,req.body.comment||null]);}await pool.query('INSERT INTO lead_comments(lead_id,user_id,comment,stage) VALUES($1,$2,$3,$4)',[req.params.id,req.user.id,req.body.comment||null,req.body.stage]);await audit(req,'LEAD_STAGE_UPDATED','lead',req.params.id);if(req.body.stage==='FOLLOW-UP')await audit(req,'LEAD_FOLLOWUP_SCHEDULED','lead',req.params.id);res.json(r.rows[0])});
app.get('/api/leads/:id/comments',auth,async(req,res)=>{const lead=await pool.query('SELECT assigned_to FROM leads WHERE id=$1',[req.params.id]);if(!lead.rows[0])return res.status(404).json({error:'Lead not found'});if(lead.rows[0].assigned_to&&!await canSeeUser(req.user,lead.rows[0].assigned_to))return res.status(403).json({error:'Not permitted'});res.json((await pool.query('SELECT lc.*,u.name user_name FROM lead_comments lc JOIN users u ON u.id=lc.user_id WHERE lead_id=$1 ORDER BY created_at DESC',[req.params.id])).rows)});
