app.get('/api/followups',auth,async(req,res)=>{const view=req.query.view||'self';const ids=await visibleUserIds(req.user);let sql="SELECT f.*,l.stage,l.customer_id,c.name customer_name,c.phone,u.name assigned_name FROM followups f JOIN leads l ON l.id=f.lead_id JOIN customers c ON c.id=l.customer_id LEFT JOIN users u ON u.id=f.assigned_to WHERE f.completed=false";const params=[];if(view==='unassigned'){sql+=' AND f.assigned_to IS NULL'}else if(view==='team'){if(!isAdmin(req.user)&&!isManager(req.user))return res.status(403).json({error:'Team follow-ups are not available for your role'});let allowed=ids;if(req.query.assignee&&req.query.assignee!=='all'){if(!ids.includes(req.query.assignee))return res.status(403).json({error:'You can only view follow-ups assigned to members of your team'});allowed=[req.query.assignee]}sql+=' AND f.assigned_to=ANY($1)';params.push(allowed)}else{sql+=' AND f.assigned_to=$1';params.push(req.user.id)}if(view==='today'||req.query.today==='true')sql+=" AND (f.due_at AT TIME ZONE 'Asia/Kolkata')::date=(now() AT TIME ZONE 'Asia/Kolkata')::date";sql+=' ORDER BY f.due_at ASC';res.json((await pool.query(sql,params)).rows)});
app.post('/api/followups',auth,async(req,res)=>{const assigned=req.body.assigned_to||req.user.id;if(!await canAssignLeadTo(req.user,assigned))return res.status(403).json({error:'You cannot assign this follow-up to that user'});const r=await pool.query('INSERT INTO followups(lead_id,assigned_to,due_at,notes) VALUES($1,$2,$3,$4) RETURNING *',[req.body.lead_id,assigned,req.body.due_at,req.body.notes]);res.status(201).json(r.rows[0])});
