app.post('/api/lenders',auth,requireAdmin,async(req,res)=>{const commission=Number(req.body.commission_pct);if(!req.body.name||!Number.isFinite(commission)||commission<0||commission>100)return res.status(400).json({error:'Lender name and a commission percentage between 0 and 100 are required'});const r=await pool.query('INSERT INTO lenders(name,contact,commission_pct) VALUES($1,$2,$3) RETURNING *',[req.body.name,req.body.contact,commission]);res.status(201).json(r.rows[0])});
