app.get('/api/cibil-reports/:id/parsed-json',auth,async(req,res)=>{
  const r=await pool.query('SELECT id,customer_id,original_name,score,total_outstanding,total_monthly_emi,total_overdue,max_dpd,summary,created_at,accepted_final FROM cibil_reports WHERE id=$1',[req.params.id]);
  if(!r.rows[0])return res.status(404).json({error:'CIBIL report not found'});
  if(!await canAccessCustomer(req.user,r.rows[0].customer_id))return res.status(403).json({error:'You cannot access this customer'});
  const accounts=await pool.query('SELECT id,lender,loan_type,account_number_masked,sanctioned_amount,outstanding_amount,emi,overdue_amount,dpd,status,created_at FROM cibil_accounts WHERE report_id=$1 ORDER BY created_at ASC',[req.params.id]);
  const summary=r.rows[0].summary||{};
  res.setHeader('Content-Type','application/json; charset=utf-8');
  res.setHeader('Content-Disposition',`attachment; filename=\"${String(r.rows[0].original_name||'cibil-report').replace(/[^a-zA-Z0-9._-]/g,'_')}-parsed.json\"`);
  res.json({source_report:{id:r.rows[0].id,original_name:r.rows[0].original_name,created_at:r.rows[0].created_at,accepted_final:r.rows[0].accepted_final},parser_version:summary.report_version||'parser-v14-cibil-sanctioned-balance-emi',summary,accounts:accounts.rows});
});

app.post('/api/cibil-reports/:id/reanalyze',auth,requireSuperAdmin,async(req,res)=>{const r=await pool.query('SELECT * FROM cibil_reports WHERE id=$1',[req.params.id]);if(!r.rows[0])return res.status(404).json({error:'CIBIL report not found'});const report=r.rows[0];if(!await canAccessCustomer(req.user,report.customer_id))return res.status(403).json({error:'You cannot access this customer'});try{let buffer;if(s3&&report.object_key){const obj=await s3.send(new GetObjectCommand({Bucket:process.env.S3_BUCKET,Key:report.object_key}));buffer=Buffer.from(await obj.Body.transformToByteArray())}else{if(!report.object_key||!fs.existsSync(report.object_key))return res.status(404).json({error:'Stored report file not found'});buffer=fs.readFileSync(report.object_key)}const parsed=await pdfParse(buffer);const analysis=analyzeCibilText(parsed.text||'');const client=await pool.connect();try{await client.query('BEGIN');await client.query('UPDATE cibil_reports SET score=$1,total_outstanding=$2,total_monthly_emi=$3,total_overdue=$4,max_dpd=$5,summary=$6,extraction_confidence=$7,extraction_note=$8,accepted_final=false,accepted_at=NULL,accepted_by=NULL,review_started_at=NULL WHERE id=$9',[analysis.score,analysis.total_outstanding,analysis.total_monthly_emi,analysis.total_overdue,analysis.max_dpd,JSON.stringify(analysis),analysis.extraction_confidence,analysis.extraction_note,report.id]);await persistParsedCibilAccounts(client,report.id,analysis);await client.query('COMMIT')}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}await audit(req,'CIBIL_REPORT_REANALYZED_V14','cibil_report',report.id);const fresh=await pool.query('SELECT * FROM cibil_reports WHERE id=$1',[report.id]);const accounts=await pool.query('SELECT * FROM cibil_accounts WHERE report_id=$1 ORDER BY outstanding_amount DESC NULLS LAST',[report.id]);res.json({...fresh.rows[0],summary:analysis,accounts:accounts.rows})}catch(e){console.error('[CIBIL REANALYZE]',e);res.status(500).json({error:'CIBIL re-analysis failed.',detail:e.message})}});
app.post('/api/cibil-reports/:id/reconcile',auth,requireSuperAdmin,async(req,res)=>{
  const r=await pool.query('SELECT * FROM cibil_reports WHERE id=$1',[req.params.id]);
  if(!r.rows[0])return res.status(404).json({error:'CIBIL report not found'});
  if(!await canAccessCustomer(req.user,r.rows[0].customer_id))return res.status(403).json({error:'You cannot access this customer'});
  if(r.rows[0].accepted_final)return res.status(409).json({error:'This report is already accepted as final.'});
  if(r.rows[0].review_started_at)return res.status(409).json({error:'This report has already been reviewed or edited. Reconciliation will not overwrite reviewed values.'});
  try{
    const a=await pool.query('SELECT * FROM cibil_accounts WHERE report_id=$1 ORDER BY created_at ASC',[req.params.id]);
    const result=await reconcileAccounts(r.rows[0],a.rows,{allowReviewedEmptySync:false,pool});
    const fresh=await pool.query('SELECT * FROM cibil_reports WHERE id=$1',[req.params.id]);
    const accounts=await pool.query('SELECT * FROM cibil_accounts WHERE report_id=$1 ORDER BY created_at ASC',[req.params.id]);
    if(result.needs_reanalysis)return res.status(409).json({error:'The stored account set does not match the parsed CIBIL report. Re-analysis is required.',code:'CIBIL_REANALYSIS_REQUIRED'});
    await audit(req,'CIBIL_REPORT_FINANCIAL_RECONCILED','cibil_report',req.params.id);
    return res.json({...fresh.rows[0],summary:{...(fresh.rows[0].summary||{}),financial_data_sync:result.synced?'SYNCHRONIZED':'OK'},accounts:accounts.rows});
  }catch(e){console.error('[CIBIL RECONCILE]',e);return res.status(500).json({error:'CIBIL financial data reconciliation failed.',detail:e.message})}
});
// Safe financial synchronization for stale/empty database values. It never overwrites non-empty reviewed values.
app.post('/api/cibil-reports/:id/financial-sync',auth,requireSuperAdmin,async(req,res)=>{
  const r=await pool.query('SELECT * FROM cibil_reports WHERE id=$1',[req.params.id]);
  if(!r.rows[0])return res.status(404).json({error:'CIBIL report not found'});
  if(!await canAccessCustomer(req.user,r.rows[0].customer_id))return res.status(403).json({error:'You cannot access this customer'});
  if(r.rows[0].accepted_final)return res.status(409).json({error:'This report is already accepted as final.'});
  try{
    const a=await pool.query('SELECT * FROM cibil_accounts WHERE report_id=$1 ORDER BY created_at ASC',[req.params.id]);
    const result=await reconcileAccounts(r.rows[0],a.rows,{allowReviewedEmptySync:true,pool});
    if(result.needs_reanalysis)return res.status(409).json({error:'The stored account set does not match the parsed CIBIL report. Re-analysis is required.',code:'CIBIL_REANALYSIS_REQUIRED'});
    const fresh=await pool.query('SELECT * FROM cibil_reports WHERE id=$1',[req.params.id]);
    const accounts=await pool.query('SELECT * FROM cibil_accounts WHERE report_id=$1 ORDER BY created_at ASC',[req.params.id]);
    await audit(req,'CIBIL_REPORT_FINANCIAL_SYNCED','cibil_report',req.params.id);
    return res.json({...fresh.rows[0],summary:{...(fresh.rows[0].summary||{}),financial_data_sync:result.synced?'SYNCHRONIZED':'OK',financial_sync_reason:result.reason},accounts:accounts.rows});
  }catch(e){console.error('[CIBIL FINANCIAL SYNC]',e);return res.status(500).json({error:'CIBIL financial synchronization failed.',detail:e.message})}
});
// CIBIL final-report editing and acceptance
app.patch('/api/cibil-accounts/:id',auth,async(req,res)=>{
  const allowed=['sanctioned_amount','outstanding_amount','emi','overdue_amount','dpd'];
  const fields=[]; const values=[];
  for(const key of allowed){
    if(Object.prototype.hasOwnProperty.call(req.body||{},key)){
      const raw=req.body[key];
      if(raw!==null && raw!=='' && !Number.isFinite(Number(raw))) return res.status(400).json({error:`Invalid value for ${key}`});
      fields.push(`${key}=$${values.length+1}`);
      values.push(raw===null||raw===''?null:Number(raw));
    }
  }
  if(!fields.length)return res.status(400).json({error:'No editable amount fields supplied'});
  const current=await pool.query('SELECT a.*,r.customer_id,r.accepted_final FROM cibil_accounts a JOIN cibil_reports r ON r.id=a.report_id WHERE a.id=$1',[req.params.id]);
  if(!current.rows[0])return res.status(404).json({error:'CIBIL account not found'});
  if(!await canAccessCustomer(req.user,current.rows[0].customer_id))return res.status(403).json({error:'You cannot access this customer'});
  if(current.rows[0].accepted_final)return res.status(409).json({error:'This report is already accepted as final. Re-analyze the report to start a new review.'});
  values.push(req.params.id);
  const r=await pool.query(`UPDATE cibil_accounts SET ${fields.join(',') } WHERE id=$${values.length} RETURNING *`,values);
  await pool.query('UPDATE cibil_reports SET review_started_at=COALESCE(review_started_at,now()) WHERE id=$1',[current.rows[0].report_id]);
  await audit(req,'CIBIL_ACCOUNT_EDITED','cibil_account',req.params.id);
  res.json(r.rows[0]);
});

